  private storeAsset(kind:string,data:{buffer:Buffer;mediaType:string;ext:'webp'|'png'|'jpg'|'ico'},width?:number,height?:number){const saved=this.assets.save(data.buffer,data.ext);this.db.prepare('INSERT INTO assets(id,kind,relative_path,media_type,byte_size,width,height,content_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?)').run(saved.id,kind,saved.relativePath,data.mediaType,saved.byteSize,width??null,height??null,saved.hash,Date.now());return saved.id;}
  async run(bookmarkId:string,replace=false){const b=this.db.prepare('SELECT * FROM bookmarks WHERE id=?').get(bookmarkId) as any;if(!b)return;let context:any;try{const url=await assertPublicUrl(b.url,this.config.allowPrivateCapture);context=await (await getBrowser()).newContext({viewport:{width:1440,height:900},acceptDownloads:false,serviceWorkers:'block'});const page=await context.newPage();await page.route('**/*',async(route:any)=>{try{await assertPublicUrl(route.request().url(),this.config.allowPrivateCapture);await route.continue();}catch{await route.abort('blockedbyclient');}});await page.goto(url,{waitUntil:'domcontentloaded',timeout:this.config.captureTimeoutMs});await page.waitForTimeout(600);const meta=await extractMetadata(page);const shot=await captureSnapshot(page,this.config.captureMaxHeight);const snapId=this.storeAsset('snapshot',{buffer:shot.buffer,mediaType:'image/webp',ext:'webp'},shot.width,shot.height);
      let faviconId:string|null=null,previewId:string|null=null; if(meta.faviconUrl){const d=await safeImageDownload(meta.faviconUrl,this.config.allowPrivateCapture).catch(()=>null);if(d)faviconId=this.storeAsset('favicon',d);}if(meta.previewUrl){const d=await safeImageDownload(meta.previewUrl,this.config.allowPrivateCapture).catch(()=>null);if(d)previewId=this.storeAsset('preview',d);}
      const now=Date.now();this.db.transaction(()=>{const old=this.db.prepare('SELECT asset_id FROM page_snapshots WHERE bookmark_id=?').get(bookmarkId) as any;this.db.prepare(`UPDATE bookmarks SET title=CASE WHEN title_source='user' AND ?=0 THEN title ELSE ? END,title_source=CASE WHEN title_source='user' AND ?=0 THEN title_source ELSE ? END,description=CASE WHEN description_source='user' AND ?=0 THEN description ELSE COALESCE(?,description) END,description_source=CASE WHEN description_source='user' AND ?=0 THEN description_source ELSE CASE WHEN ? IS NULL THEN description_source ELSE 'retrieved' END END,favicon_asset_id=COALESCE(?,favicon_asset_id),preview_asset_id=COALESCE(?,preview_asset_id),metadata_status=?,metadata_error_code=NULL,metadata_refreshed_at=?,updated_at=? WHERE id=?`).run(replace?1:0,meta.title??new URL(url).hostname,replace?1:0,meta.title?'retrieved':'fallback',replace?1:0,meta.description,replace?1:0,meta.description,faviconId,previewId,(meta.description&&faviconId&&previewId)?'complete':'partial',now,now,bookmarkId);this.db.prepare(`UPDATE page_snapshots SET asset_id=?,status=?,captured_url=?,captured_at=?,limitation_code=?,error_message=NULL,refresh_status=NULL,updated_at=? WHERE bookmark_id=?`).run(snapId,shot.partial?'partial':'complete',page.url(),now,shot.partial?'HEIGHT_LIMIT':null,now,bookmarkId);this.db.prepare("UPDATE capture_jobs SET status=?,finished_at=? WHERE bookmark_id=? AND status='processing'").run(shot.partial?'partial':'succeeded',now,bookmarkId);if(old?.asset_id)this.db.prepare('DELETE FROM assets WHERE id=?').run(old.asset_id);})();
    }catch(e:any){const now=Date.now(),message=e?.message?.slice(0,300)??'Capture failed';this.db.prepare("UPDATE bookmarks SET metadata_status='failed',metadata_error_code='CAPTURE_FAILED',metadata_refreshed_at=?,updated_at=? WHERE id=?").run(now,now,bookmarkId);this.db.prepare("UPDATE page_snapshots SET status=CASE WHEN asset_id IS NULL THEN 'failed' ELSE status END,refresh_status=CASE WHEN asset_id IS NULL THEN NULL ELSE 'failed' END,error_message=?,limitation_code='CAPTURE_FAILED',updated_at=? WHERE bookmark_id=?").run(message,now,bookmarkId);this.db.prepare("UPDATE capture_jobs SET status='failed',finished_at=?,error_code='CAPTURE_FAILED' WHERE bookmark_id=? AND status='processing'").run(now,bookmarkId);}finally{await context?.close();}}
}

