import Fastify from 'fastify';
import fastifyStatic from '@fastify/static';
import path from 'node:path';
import fs from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { BulkRequest, CreateBookmark, Filters, Preferences, SavedViewInput, UpdateBookmark } from '@bookmark/contracts';
import type { Config } from './config.js';
import { createDatabase } from './db/client.js';
import { BookmarkRepository } from './db/bookmark-repository.js';
import { BookmarkService } from './domain/bookmark-service.js';
import { AssetStore } from './storage/asset-store.js';
import { CaptureService } from './capture/capture-service.js';
import { JobWorker } from './capture/job-worker.js';
import { parseSearch } from './search/parser.js';
import { SearchSyntaxError } from './search/ast.js';

const fold=(s:string)=>s.normalize('NFKC').toLocaleLowerCase();
export async function buildApp(config:Config){
  const app=Fastify({logger:true}); const db=createDatabase(config);const repo=new BookmarkRepository(db);const service=new BookmarkService(repo);const assets=new AssetStore(config);const worker=new JobWorker(db,new CaptureService(db,config,assets));worker.start();
  app.setErrorHandler((err:any,_req,reply)=>{const status=err instanceof SearchSyntaxError?422:(err.statusCode??500);const detail=err instanceof SearchSyntaxError?err.detail:{code:err.code??(status===500?'INTERNAL_ERROR':'INVALID_REQUEST'),message:status===500?'The request could not be completed.':err.message,existingBookmarkId:err.existingBookmarkId};reply.code(status).send({error:detail,...(err.existingBookmarkId?{existingBookmarkId:err.existingBookmarkId}:{})});});
  app.get('/api/health',async()=>({status:'ok'}));app.get('/api/ready',async()=>({status:'ready'}));
  app.get('/api/bookmarks',async(req:any)=>{const q=req.query??{};const filters:Filters={archiveState:q.archiveState??'active',readState:q.readState||undefined,favorite:q.favorite===undefined?undefined:q.favorite==='true'||q.favorite===true,tags:q.tag?Array.isArray(q.tag)?q.tag:[q.tag]:undefined};const all=repo.list(parseSearch(q.q??''),filters,q.sort??'createdAt',q.direction??'desc');const offset=Number(q.cursor??0),limit=Math.min(100,Math.max(1,Number(q.limit??50)));return{items:all.slice(offset,offset+limit),total:all.length,nextCursor:offset+limit<all.length?String(offset+limit):null};});
  app.post('/api/bookmarks',async(req:any,reply)=>reply.code(202).send(service.create(req.body as CreateBookmark)));
  app.get('/api/bookmarks/:id',async(req:any,reply)=>{const b=repo.get(req.params.id);if(!b)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Bookmark not found'}});return b;});
  app.patch('/api/bookmarks/:id',async(req:any)=>service.update(req.params.id,req.body as UpdateBookmark));
  app.delete('/api/bookmarks/:id',async(req:any,reply)=>{if(req.query.confirm!=='true'&&req.query.confirm!==true)return reply.code(422).send({error:{code:'CONFIRMATION_REQUIRED',message:'Deletion must be confirmed'}});if(!repo.delete(req.params.id))return reply.code(404).send({error:{code:'NOT_FOUND',message:'Bookmark not found'}});return reply.code(204).send();});
  app.post('/api/bookmarks/:id/refresh',async(req:any,reply)=>{const b=repo.get(req.params.id);if(!b)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Bookmark not found'}});const active=db.prepare("SELECT id FROM capture_jobs WHERE bookmark_id=? AND status IN ('pending','processing')").get(b.id);if(active)return reply.code(409).send({error:{code:'CAPTURE_IN_PROGRESS',message:'A refresh is already running'}});const now=Date.now();db.prepare("INSERT INTO capture_jobs(id,bookmark_id,kind,status,replace_user_metadata,attempt_count,available_at,created_at) VALUES(?,?,?,'pending',?,0,?,?)").run(randomUUID(),b.id,'refresh',(req.body as any)?.replaceUserMetadata?1:0,now,now);db.prepare("UPDATE page_snapshots SET refresh_status='pending',updated_at=? WHERE bookmark_id=?").run(now,b.id);return reply.code(202).send(repo.get(b.id));});
  app.get('/api/bookmarks/:id/snapshot',async(req:any,reply)=>{const b=repo.get(req.params.id);if(!b)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Bookmark not found'}});return b.snapshot;});
  app.get('/api/assets/:id',async(req:any,reply)=>{const row=db.prepare('SELECT * FROM assets WHERE id=?').get(req.params.id) as any;if(!row)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Asset not found'}});reply.header('Content-Type',row.media_type).header('X-Content-Type-Options','nosniff').header('Content-Security-Policy',"default-src 'none'; sandbox").header('Cache-Control','private, max-age=3600');return reply.send(fs.createReadStream(assets.pathFor(row.relative_path)));});
  app.get('/api/tags',async(req:any)=>({items:repo.suggestTags(req.query?.q??'')}));
  const resolve=(selector:any)=>selector.mode==='explicit'?selector.ids.map((id:string)=>repo.get(id)).filter(Boolean):repo.list(parseSearch(selector.query??''),selector.filters??{},'createdAt','desc').filter(b=>!selector.excludedIds?.includes(b.id));
  app.post('/api/bulk/preview',async(req:any)=>{const body=req.body as BulkRequest;return{targetCount:resolve(body.selector).length,action:body.action};});
  app.post('/api/bulk/execute',async(req:any,reply)=>{const body=req.body as BulkRequest;const targets=resolve(body.selector);if(body.confirmedTargetCount!==targets.length)return reply.code(409).send({error:{code:'STALE_SELECTION',message:'The matching count changed; preview again.'}});const tx=db.transaction(()=>{for(const b of targets){if(body.action.type==='delete')repo.delete(b.id);else if(body.action.type==='archive')repo.update(b.id,{archiveState:'archived'});else repo.update(b.id,{tags:[...b.tags.map(t=>t.name),body.action.tag]});}});tx();return{targetCount:targets.length,affectedCount:targets.length,failed:[]};});
  app.get('/api/saved-views',async()=>db.prepare('SELECT * FROM saved_views ORDER BY normalized_name').all().map(mapView));
  app.post('/api/saved-views',async(req:any,reply)=>{const v=req.body as SavedViewInput;parseSearch(v.query);const now=Date.now(),id=randomUUID();try{db.prepare('INSERT INTO saved_views VALUES(?,?,?,?,?,?,?,?,?)').run(id,v.name.trim(),fold(v.name),v.query,JSON.stringify(v.filters),v.sort,v.direction,now,now);}catch(e:any){if(e.code?.startsWith('SQLITE_CONSTRAINT'))return reply.code(409).send({error:{code:'DUPLICATE_NAME',message:'A saved view already uses that name.'}});throw e;}return reply.code(201).send(mapView(db.prepare('SELECT * FROM saved_views WHERE id=?').get(id)));});
  app.patch('/api/saved-views/:id',async(req:any,reply)=>{const v=req.body as SavedViewInput;parseSearch(v.query);try{const result=db.prepare('UPDATE saved_views SET name=?,normalized_name=?,query=?,filters_json=?,sort_field=?,sort_direction=?,updated_at=? WHERE id=?').run(v.name.trim(),fold(v.name),v.query,JSON.stringify(v.filters),v.sort,v.direction,Date.now(),req.params.id);if(!result.changes)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Saved view not found'}});}catch(e:any){if(e.code?.startsWith('SQLITE_CONSTRAINT'))return reply.code(409).send({error:{code:'DUPLICATE_NAME',message:'A saved view already uses that name.'}});throw e;}return mapView(db.prepare('SELECT * FROM saved_views WHERE id=?').get(req.params.id));});
  app.delete('/api/saved-views/:id',async(req:any,reply)=>{if(!db.prepare('DELETE FROM saved_views WHERE id=?').run(req.params.id).changes)return reply.code(404).send({error:{code:'NOT_FOUND',message:'Saved view not found'}});return reply.code(204).send();});
  app.get('/api/preferences',async()=>{const p=db.prepare("SELECT theme,density FROM preferences WHERE singleton_key='default'").get();return p;});
  app.patch('/api/preferences',async(req:any)=>{const p=req.body as Preferences;if(!['system','light','dark'].includes(p.theme)||!['comfortable','compact'].includes(p.density)){const e:any=new Error('Invalid display preference');e.statusCode=422;throw e;}db.prepare("UPDATE preferences SET theme=?,density=?,updated_at=? WHERE singleton_key='default'").run(p.theme,p.density,Date.now());return p;});
  const webRoot=path.resolve(process.cwd(),'apps/web/dist');if(fs.existsSync(webRoot)){await app.register(fastifyStatic,{root:webRoot,wildcard:false});app.setNotFoundHandler((req,reply)=>req.raw.url?.startsWith('/api/')?reply.code(404).send({error:{code:'NOT_FOUND',message:'Not found'}}):reply.sendFile('index.html'));}
  app.addHook('onClose',async()=>{await worker.stop();db.close();});return app;
}
function mapView(r:any){return{id:r.id,name:r.name,query:r.query,filters:JSON.parse(r.filters_json),sort:r.sort_field,direction:r.sort_direction,createdAt:new Date(r.created_at).toISOString(),updatedAt:new Date(r.updated_at).toISOString()};}

