'Saving…':bookmark?'Save changes':'Save & capture'}</button></footer></form></div>}
function Snapshot({b,onClose,onRefresh}:{b:Bookmark;onClose:()=>void;onRefresh:()=>void}){return <div className="modal snapshot-modal" role="dialog" aria-modal="true"><div><button className="close" onClick={onClose}>×</button><p className="eyebrow">SAVED COPY</p><h2>{b.title}</h2><p>Captured {b.snapshot.capturedAt?new Date(b.snapshot.capturedAt).toLocaleString():'—'} · {b.snapshot.status}</p>{b.snapshot.assetUrl?<img src={b.snapshot.assetUrl} alt={`Saved view of ${b.title}`}/>:<div className="state">No snapshot is available.</div>}<footer><a className="button" href={b.url} target="_blank">Open live page</a><button onClick={onRefresh}>Refresh snapshot</button></footer></div></div>}
