isplay:flex;gap:5px;flex-wrap:wrap;min-height:24px}.tags span{font-size:10px;color:#4b6753;background:#e8f0e9;border-radius:5px;padding:4px 7px}.meta{border-top:1px solid #ece8de;margin-top:10px;padding-top:10px;display:flex;justify-content:space-between;font-size:10px;color:#999486}.status{color:var(--green)}.status.pending{color:#ae7b2c}.status.failed{color:#a54a3a}.actions{display:flex;gap:4px;flex-wrap:wrap;margin-top:10px}.actions button{border:0;background:#f3f1eb;color:#656157;border-radius:5px;padding:5px 7px;font-size:9px}.actions .delete,.delete{color:#ad4938}.empty,.state{text-align:center;padding:90px 20px;color:var(--muted)}.empty>div{font-size:48px;color:#b5a886}.empty h2{font-family:'DM Serif Display';font-size:28px;color:var(--ink);font-weight:400;margin:10px}.selection{position:sticky;top:10px;z-index:5;background:#2f362f;color:white;padding:11px 14px;border-radius:9px;display:flex;gap:9px;align-items:center;margin-bottom:16px;box-shadow:0 5px 20px #0002}.selection strong{margin-right:auto}.selection button{border:0;border-radius:5px;padding:7px 10px}.selection .danger{background:#b04d3b;color:white}.error{padding:11px 14px;background:#f8e1dc;color:#8e382c;border-radius:8px;margin:10px 0}.modal{position:fixed;inset:0;background:#191b18b8;z-index:10;display:grid;place-items:center;padding:20px}.modal form,.snapshot-modal>div{background:var(--paper);padding:28px;border-radius:15px;width:min(620px,100%);max-height:92vh;overflow:auto;position:relative}.modal h2{font-family:'DM Serif Display';font-size:30px;font-weight:400;margin:0 0 22px}.close{position:absolute;right:14px;top:12px;border:0;background:none;font-size:28px}.modal label{display:grid;gap:6px;font-size:12px;font-weight:600;margin:12px 0}.modal label small{color:var(--muted);font-weight:400}.modal input,.modal textarea{border:1px solid var(--line);background:white;border-radius:7px;padding:10px;outline:none}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.toggle{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.modal footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.modal footer button,.modal footer .button{border:1px solid var(--line);border-radius:8px;padding:10px 14px;text-decoration:none}.snapshot-modal>div{width:min(1000px,100%)}.snapshot-modal img{width:100%;max-height:65vh;object-fit:contain;background:#ddd}.view-list{display:grid;gap:10px}.view-list article{background:white;border:1px solid var(--line);border-radius:10px;padding:18px;display:flex;align-items:center;gap:10px}.view-list article div{flex:1}.view-list h2{font-family:'DM Serif Display';font-weight:400;margin:0}.view-list code{color:var(--accent)}.view-list button{border:1px solid var(--line);background:white;padding:8px 11px;border-radius:7px}.settings{max-width:760px}.settings h2{font-family:'DM Serif Display';font-weight:400;font-size:28px;margin-bottom:4px}.settings>p{color:var(--muted)}fieldset{border:0;padding:0;margin:30px 0}legend{font-weight:700;margin-bottom:10px}.settings fieldset{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.settings label{border:1px solid var(--line);background:white;border-radius:10px;padding:16px;display:grid;gap:4px}.settings label.chosen{border-color:var(--accent);box-shadow:0 0 0 2px #da5b3620}.settings label input{position:absolute;opacity:0}.settings label small{color:var(--muted)}.theme-swatch{height:54px;border-radius:6px;margin-bottom:8px;border:1px solid var(--line)}.theme-swatch.system{background:linear-gradient(90deg,#f6f2e7 50%,#27302a 50%)}.theme-swatch.light{background:#f6f2e7}.theme-swatch.dark{background:#27302a}
