     1	import { useEffect,useMemo,useState } from 'react';
     2	import type { Bookmark,BulkAction,Filters,Preferences,ResultSelector,SavedView,SortDirection,SortField } from '@bookmark/contracts';
     3	import {api,ApiError} from './api/client';
     4	
     5	type Page='collection'|'unread'|'archived'|'saved'|'settings';
     6	const emptyFilters:Filters={archiveState:'active'};
     7	export function App(){const[page,setPage]=useState<Page>('collection'),[items,setItems]=useState<Bookmark[]>([]),[total,setTotal]=useState(0),[loading,setLoading]=useState(true),[q,setQ]=useState(''),[filters,setFilters]=useState<Filters>(emptyFilters),[sort,setSort]=useState<SortField>('createdAt'),[direction,setDirection]=useState<SortDirection>('desc'),[error,setError]=useState(''),[add,setAdd]=useState(false),[edit,setEdit]=useState<Bookmark|null>(null),[snapshot,setSnapshot]=useState<Bookmark|null>(null),[selected,setSelected]=useState<Set<string>>(new Set()),[allResults,setAllResults]=useState(false),[views,setViews]=useState<SavedView[]>([]),[prefs,setPrefs]=useState<Preferences>({theme:'system',density:'comfortable'});
     8	  const effectiveFilters=useMemo(()=>page==='unread'?{...filters,archiveState:'active' as const,readState:'unread' as const}:page==='archived'?{...filters,archiveState:'archived' as const}:filters,[page,filters]);
     9	  async function load(){setLoading(true);try{const r=await api.list({q,filters:effectiveFilters,sort,direction});setItems(r.items);setTotal(r.total);setError('')}catch(e){setError(e instanceof ApiError?e.message:'Could not load bookmarks')}finally{setLoading(false)}}
    10	  useEffect(()=>{void load()},[q,JSON.stringify(effectiveFilters),sort,direction]);useEffect(()=>{api.views().then(setViews);api.preferences().then(p=>{setPrefs(p);applyPrefs(p)}).catch(()=>{})},[]);useEffect(()=>{setSelected(new Set());setAllResults(false)},[q,JSON.stringify(effectiveFilters)]);
    11	  const selector:ResultSelector=allResults?{mode:'allResults',query:q,filters:effectiveFilters,excludedIds:[]}:{mode:'explicit',ids:[...selected]};
    12	  async function bulk(action:BulkAction){try{const p=await api.bulkPreview(selector,action);if(!confirm(`${action.type==='delete'?'Permanently delete':action.type==='archive'?'Archive':'Tag'} ${p.targetCount} bookmark${p.targetCount===1?'':'s'}?`))return;await api.bulkExecute(selector,action,p.targetCount);setSelected(new Set());setAllResults(false);await load()}catch(e){setError(e instanceof Error?e.message:'Bulk action failed')}}
    13	  function openView(v:SavedView){setQ(v.query);setFilters(v.filters);setSort(v.sort);setDirection(v.direction);setPage('collection')}
    14	  return <div className="app" data-theme={prefs.theme} data-density={prefs.density} data-harness-ready={!loading?'true':undefined}>
    15	    <aside className="sidebar"><div className="brand"><span className="brand-mark">L</span><div><strong>Latchmark</strong><small>Your quiet corner of the web</small></div></div><nav>{([['collection','All bookmarks','⌘'],['unread','Read later','◷'],['archived','Archived','□'],['saved','Saved views','◇'],['settings','Settings','⚙']] as [Page,string,string][]).map(([id,label,icon])=><button key={id} className={page===id?'active':''} onClick={()=>setPage(id)}><span>{icon}</span>{label}{id==='unread'&&<em>{items.filter(x=>x.readState==='unread').length||''}</em>}</button>)}</nav><div className="sidebar-foot"><span className="pulse"/>Stored on this device</div></aside>
    16	    <main><header><div><p className="eyebrow">PERSONAL LIBRARY</p><h1>{page==='unread'?'Read later':page==='archived'?'Archived':page==='saved'?'Saved views':page==='settings'?'Settings':'All bookmarks'}</h1><p className="subtitle">{page==='settings'?'Make this space feel like yours.':page==='saved'?'Return to the searches that matter.':`${total} ${total===1?'place':'places'} worth returning to`}</p></div>{!['settings','saved'].includes(page)&&<button className="primary" onClick={()=>setAdd(true)}>＋ Add bookmark</button>}</header>
    17	      {page==='settings'?<Settings prefs={prefs} onChange={async p=>{setPrefs(p);applyPrefs(p);await api.savePreferences(p)}}/>:page==='saved'?<SavedViews views={views} onOpen={openView} onDelete={async id=>{await api.deleteView(id);setViews(await api.views())}}/>:<>
    18	        <section className="toolbar"><label className="search"><span>⌕</span><input aria-label="Search bookmarks" value={q} onChange={e=>setQ(e.target.value)} placeholder={'Search titles, notes, or try #design NOT "case study"'}/>{q&&<button onClick={()=>setQ('')}>×</button>}</label><select aria-label="Filter" value={filters.favorite===true?'favorite':'all'} onChange={e=>setFilters(f=>({...f,favorite:e.target.value==='favorite'?true:undefined}))}><option value="all">All bookmarks</option><option value="favorite">Favorites</option></select><select aria-label="Sort" value={`${sort}:${direction}`} onChange={e=>{const[s,d]=e.target.value.split(':') as[SortField,SortDirection];setSort(s);setDirection(d)}}><option value="createdAt:desc">Newest saved</option><option value="createdAt:asc">Oldest saved</option><option value="updatedAt:desc">Recently updated</option><option value="title:asc">Title A–Z</option><option value="destination:asc">Website A–Z</option></select><button className="quiet" onClick={async()=>{const name=prompt('Name this saved view');if(name){await api.createView({name,query:q,filters:effectiveFilters,sort,direction});setViews(await api.views())}}}>◇ Save view</button></section>
    19	        {error&&<div className="error" role="alert">{error}</div>}{(selected.size>0||allResults)&&<div className="selection"><strong>{allResults?`All ${total} results selected`:`${selected.size} selected`}</strong>{!allResults&&selected.size===items.length&&total>items.length&&<button onClick={()=>setAllResults(true)}>Select all {total} results</button>}<button onClick={()=>{const tag=prompt('Tag to add');if(tag)void bulk({type:'addTag',tag})}}>Add tag</button><button onClick={()=>void bulk({type:'archive'})}>Archive</button><button className="danger" onClick={()=>void bulk({type:'delete'})}>Delete</button><button onClick={()=>{setSelected(new Set());setAllResults(false)}}>Clear</button></div>}
    20	        {loading?<div className="state">Gathering your bookmarks…</div>:items.length===0?<div className="empty"><div>⌁</div><h2>{q?'No places match that search':'Your library is waiting'}</h2><p>{q?'Try changing the words or filters.':'Save your first corner of the web and we’ll keep a copy close.'}</p>{!q&&<button className="primary" onClick={()=>setAdd(true)}>Add your first bookmark</button>}</div>:<section className="grid">{items.map(b=><Card key={b.id} b={b} checked={selected.has(b.id)||allResults} onCheck={()=>{const n=new Set(selected);n.has(b.id)?n.delete(b.id):n.add(b.id);setSelected(n);setAllResults(false)}} onEdit={()=>setEdit(b)} onSnapshot={()=>setSnapshot(b)} onChange={async patch=>{await api.update(b.id,patch);await load()}} onDelete={async()=>{if(confirm(`Delete “${b.title}” permanently?`)){await api.remove(b.id);await load()}}}/>)}</section>}
    21	      </>}
    22	    </main>{add&&<Editor onClose={()=>setAdd(false)} onSave={async body=>{await api.create(body);setAdd(false);await load()}}/>}{edit&&<Editor bookmark={edit} onClose={()=>setEdit(null)} onSave={async body=>{await api.update(edit.id,body);setEdit(null);await load()}}/>}{snapshot&&<Snapshot b={snapshot} onClose={()=>setSnapshot(null)} onRefresh={async()=>{await api.refresh(snapshot.id,false);setSnapshot(null);await load()}}/>}
    23	  </div>}
    24	function Card({b,checked,onCheck,onEdit,onSnapshot,onChange,onDelete}:{b:Bookmark;checked:boolean;onCheck:()=>void;onEdit:()=>void;onSnapshot:()=>void;onChange:(x:any)=>void;onDelete:()=>void}){return <article className={`card ${checked?'selected':''}`}><label className="check"><input type="checkbox" checked={checked} onChange={onCheck}/><span/></label>{b.previewUrl?<img className="preview" src={b.previewUrl} alt=""/>:<div className="preview placeholder">{new URL(b.url).hostname.slice(0,1).toUpperCase()}</div>}<div className="card-body"><div className="site">{b.faviconUrl&&<img src={b.faviconUrl} alt=""/>}<span>{new URL(b.url).hostname}</span><button className={`star ${b.isFavorite?'on':''}`} aria-label="Favorite" onClick={()=>onChange({isFavorite:!b.isFavorite})}>☆</button></div><h2><a href={b.url} target="_blank" rel="noreferrer">{b.title}</a></h2><p>{b.description||b.notes||'No description yet.'}</p><div className="tags">{b.tags.map(t=><span key={t.id}>#{t.name}</span>)}</div><div className="meta"><span>{new Date(b.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><span className={`status ${b.snapshot.status}`}>● {b.snapshot.status==='pending'?'Capturing':b.snapshot.available?'Snapshot saved':'No snapshot'}</span></div><div className="actions"><button onClick={()=>onChange({readState:b.readState==='read'?'unread':'read'})}>{b.readState==='unread'?'✓ Mark read':'◷ Read later'}</button><button disabled={!b.snapshot.available} onClick={onSnapshot}>▧ Snapshot</button><button onClick={onEdit}>Edit</button><button onClick={()=>onChange({archiveState:b.archiveState==='active'?'archived':'active'})}>{b.archiveState==='active'?'Archive':'Restore'}</button><button className="delete" onClick={onDelete}>Delete</button></div></div></article>}
    25	function Editor({bookmark,onClose,onSave}:{bookmark?:Bookmark;onClose:()=>void;onSave:(x:any)=>Promise<void>}){const[url,setUrl]=useState(bookmark?.url??''),[title,setTitle]=useState(bookmark?.title??''),[description,setDescription]=useState(bookmark?.description??''),[notes,setNotes]=useState(bookmark?.notes??''),[tags,setTags]=useState(bookmark?.tags.map(t=>t.name).join(', ')??''),[unread,setUnread]=useState(bookmark?.readState==='unread'),[busy,setBusy]=useState(false),[err,setErr]=useState('');return <div className="modal" role="dialog" aria-modal="true"><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSave({url,title:title||undefined,description:description||undefined,notes:notes||undefined,tags:tags.split(',').map(x=>x.trim()).filter(Boolean),readState:unread?'unread':'read'})}catch(x){setErr(x instanceof Error?x.message:'Could not save');setBusy(false)}}><button type="button" className="close" onClick={onClose}>×</button><p className="eyebrow">{bookmark?'EDIT PLACE':'SAVE A PLACE'}</p><h2>{bookmark?'Tune the details':'What should we remember?'}</h2><label>Web address<input required autoFocus value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://…"/></label><div className="two"><label>Title <small>optional — we’ll find it</small><input value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Tags <small>comma separated</small><input value={tags} onChange={e=>setTags(e.target.value)} placeholder="design, reading"/></label></div><label>Description<textarea value={description} onChange={e=>setDescription(e.target.value)} rows={2}/></label><label>Notes<textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={3}/></label><label className="toggle"><input type="checkbox" checked={unread} onChange={e=>setUnread(e.target.checked)}/> Add to Read later</label>{err&&<div className="error">{err}</div>}<footer><button type="button" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving…':bookmark?'Save changes':'Save & capture'}</button></footer></form></div>}
    26	function Snapshot({b,onClose,onRefresh}:{b:Bookmark;onClose:()=>void;onRefresh:()=>void}){return <div className="modal snapshot-modal" role="dialog" aria-modal="true"><div><button className="close" onClick={onClose}>×</button><p className="eyebrow">SAVED COPY</p><h2>{b.title}</h2><p>Captured {b.snapshot.capturedAt?new Date(b.snapshot.capturedAt).toLocaleString():'—'} · {b.snapshot.status}</p>{b.snapshot.assetUrl?<img src={b.snapshot.assetUrl} alt={`Saved view of ${b.title}`}/>:<div className="state">No snapshot is available.</div>}<footer><a className="button" href={b.url} target="_blank">Open live page</a><button onClick={onRefresh}>Refresh snapshot</button></footer></div></div>}
    27	function SavedViews({views,onOpen,onDelete}:{views:SavedView[];onOpen:(v:SavedView)=>void;onDelete:(id:string)=>void}){return views.length?<section className="view-list">{views.map(v=><article key={v.id}><div><span>◇</span><h2>{v.name}</h2><code>{v.query||'All bookmarks'}</code><p>{v.sort} · {v.direction}</p></div><button onClick={()=>onOpen(v)}>Open view</button><button className="delete" onClick={()=>onDelete(v.id)}>Delete</button></article>)}</section>:<div className="empty"><div>◇</div><h2>No saved views yet</h2><p>Build a search in your library, then save it for later.</p></div>}
    28	function Settings({prefs,onChange}:{prefs:Preferences;onChange:(p:Preferences)=>void}){return <section className="settings"><h2>Appearance</h2><p>Choose the mood and rhythm of your library.</p><fieldset><legend>Theme</legend>{(['system','light','dark'] as const).map(x=><label key={x} className={prefs.theme===x?'chosen':''}><input type="radio" name="theme" checked={prefs.theme===x} onChange={()=>onChange({...prefs,theme:x})}/><span className={`theme-swatch ${x}`}/><strong>{x[0]!.toUpperCase()+x.slice(1)}</strong><small>{x==='system'?'Follow this device':`${x} appearance`}</small></label>)}</fieldset><fieldset><legend>Information density</legend>{(['comfortable','compact'] as const).map(x=><label key={x} className={prefs.density===x?'chosen':''}><input type="radio" name="density" checked={prefs.density===x} onChange={()=>onChange({...prefs,density:x})}/><strong>{x[0]!.toUpperCase()+x.slice(1)}</strong><small>{x==='comfortable'?'More breathing room':'See more at once'}</small></label>)}</fieldset></section>}
    29	function applyPrefs(p:Preferences){document.documentElement.dataset.theme=p.theme;document.documentElement.dataset.density=p.density}

