const patch = "*** Begin Patch
*** Add File: /work/apps/server/src/logging.ts
+export const loggerOptions={redact:['req.body.notes','req.body.query','bookmark.notes','pageContent'],level:process.env.LOG_LEVEL??'info'};
*** Add File: /work/apps/server/src/api/errors.ts
+export function errorEnvelope(code:string,message:string){return{error:{code,message}}}
*** Add File: /work/apps/server/src/api/system-routes.ts
+import type {FastifyInstance}from'fastify';export async function systemRoutes(app:FastifyInstance){app.get('/health',async()=>({status:'ok'}));app.get('/ready',async()=>({status:'ready'}));}
*** Add File: /work/apps/web/src/components/AppShell.tsx
+import type{ReactNode}from'react';export function AppShell({children}:{children:ReactNode}){return <>{children}</>}
*** Add File: /work/apps/server/tests/helpers/database.ts
+import{mkdtempSync}from'node:fs';import{tmpdir}from'node:os';import path from'node:path';export const temporaryDataDir=()=>mkdtempSync(path.join(tmpdir(),'latchmark-test-'));
*** Add File: /work/apps/server/tests/unit/config.test.ts
+import{expect,it}from'vitest';import{loadConfig}from'../../src/config.js';it('uses the required production defaults',()=>{const c=loadConfig({});expect(c.host).toBe('0.0.0.0');expect(c.port).toBe(4000)});
*** Add File: /work/apps/server/tests/unit/asset-store.test.ts
+import{expect,it}from'vitest';import{mkdtempSync,rmSync}from'node:fs';import{tmpdir}from'node:os';import path from'node:path';import{AssetStore}from'../../src/storage/asset-store.js';it('rejects traversal',()=>{const dataDir=mkdtempSync(path.join(tmpdir(),'assets-'));const s=new AssetStore({host:'',port:0,dataDir,captureTimeoutMs:1,captureMaxHeight:1,captureConcurrency:1,allowPrivateCapture:false});expect(()=>s.pathFor('../secret')).toThrow();rmSync(dataDir,{recursive:true,force:true})});
*** Add File: /work/apps/server/tests/unit/logging.test.ts
+import{expect,it}from'vitest';import{loggerOptions}from'../../src/logging.js';it('redacts private bookmark and capture values',()=>expect(loggerOptions.redact).toContain('req.body.notes'));
*** Add File: /work/apps/server/tests/integration/lifecycle.test.ts
+import{expect,it}from'vitest';import{buildApp}from'../../src/app.js';import{temporaryDataDir}from'../helpers/database.js';it('reports health and readiness',async()=>{const app=await buildApp({host:'127.0.0.1',port:0,dataDir:temporaryDataDir(),captureTimeoutMs:10,captureMaxHeight:100,captureConcurrency:1,allowPrivateCapture:false});expect((await app.inject('/api/health')).statusCode).toBe(200);expect((await app.inject('/api/ready')).statusCode).toBe(200);await app.close()});
*** Add File: /work/apps/web/tests/api/client.test.ts
+import{expect,it}from'vitest';import{api}from'../../src/api/client';it('exposes the typed bookmark operations',()=>expect(typeof api.list).toBe('function'));
*** End Patch";
text(await tools.apply_patch(patch));

